public class ClampCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Clamp impl) {
        try {
            return ClampChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectClamp()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectClamp()));
        check("rejects the exclusive-bounds bug", false, verdict(new ExclusiveBoundsClamp()));
        check("rejects the swapped-ends bug", false, verdict(new SwappedEndsClamp()));
        check("rejects the zero-width-range bug", false, verdict(new ZeroWidthRangeClamp()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectClamp implements Clamp {
    public int clamp(int value, int lo, int hi) {
        if (value < lo) return lo;
        if (value > hi) return hi;
        return value;
    }
}

class AlsoCorrectClamp implements Clamp {
    public int clamp(int value, int lo, int hi) {
        return Math.max(lo, Math.min(hi, value));
    }
}

class ExclusiveBoundsClamp implements Clamp {
    public int clamp(int value, int lo, int hi) {
        if (value < lo) return lo;
        if (value > hi) return hi;
        if (value == lo) return lo + 1;
        if (value == hi) return hi - 1;
        return value;
    }
}

class SwappedEndsClamp implements Clamp {
    public int clamp(int value, int lo, int hi) {
        if (value < lo) return hi;
        if (value > hi) return lo;
        return value;
    }
}

class ZeroWidthRangeClamp implements Clamp {
    public int clamp(int value, int lo, int hi) {
        if (lo == hi) return value;
        if (value < lo) return lo;
        if (value > hi) return hi;
        return value;
    }
}

