/**
 * TASK: Write the checks that decide whether a Clamp is correct.
 *
 * The Clamp contract (lo is always <= hi, and the two may be EQUAL):
 *   clamp(value, lo, hi) returns lo when value < lo,
 *                        returns hi when value > hi,
 *                        and returns value itself otherwise.
 *   Both ends are INCLUSIVE: a value exactly equal to lo or to hi comes back
 *   unchanged. When lo == hi the answer is always lo.
 *   Examples: clamp(5, 0, 10) -> 5, clamp(0, 0, 10) -> 0, clamp(10, 0, 10) -> 10,
 *             clamp(-3, 0, 10) -> 0, clamp(99, 0, 10) -> 10, clamp(7, 4, 4) -> 4
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Wrap your calls in try/catch and
 * return false if the implementation throws -- a crash is a failure too.
 *
 * Every bug here lives at an edge: exactly on a bound, outside the range, or in
 * a range with no width at all. A comfortable value in the middle catches none.
 */
interface Clamp {
    /* Provided -- do not edit. */
    int clamp(int value, int lo, int hi);
}

public class ClampChecker {

    public static boolean isCorrect(Clamp impl) {
        try {
            if (impl.clamp(5, 0, 10) != 5) return false;
            if (impl.clamp(0, 0, 10) != 0) return false;
            if (impl.clamp(10, 0, 10) != 10) return false;
            if (impl.clamp(-3, 0, 10) != 0) return false;
            if (impl.clamp(99, 0, 10) != 10) return false;
            if (impl.clamp(7, 4, 4) != 4) return false;
            if (impl.clamp(-5, -10, -1) != -5) return false;
            if (impl.clamp(-20, -10, -1) != -10) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
